const date = $('Calendar Slot Trigger').first().json.date;

if (!date) {
  throw new Error('No date was provided.');
}

const zoneOffset = '+03:00';
const slotMinutes = 30;
const workStartHour = 9;
const workEndHour = 17;

// Parse the requested date safely.
const dateCheck = new Date(`${date}T12:00:00Z`);

if (Number.isNaN(dateCheck.getTime())) {
  throw new Error(`Invalid date: ${date}`);
}

// Sunday = 0, Monday = 1, ..., Thursday = 4
const weekday = dateCheck.getUTCDay();
const allowedDays = new Set([0, 1, 2, 3, 4]);

if (!allowedDays.has(weekday)) {
  return [
    {
      json: {
        success: true,
        date,
        timezone: 'Asia/Riyadh',
        duration_minutes: slotMinutes,
        slots: [],
        available_count: 0,
        message: 'No demo appointments are offered on this day.'
      }
    }
  ];
}

// Saudi Arabia is UTC+3 year-round.
const dayStartMs = new Date(`${date}T00:00:00${zoneOffset}`).getTime();
const nextDayStartMs = new Date(`${date}T00:00:00${zoneOffset}`).getTime()
  + (24 * 60 * 60 * 1000);

const businessStartMs =
  new Date(
    `${date}T${String(workStartHour).padStart(2, '0')}:00:00${zoneOffset}`
  ).getTime();

const businessEndMs =
  new Date(
    `${date}T${String(workEndHour).padStart(2, '0')}:00:00${zoneOffset}`
  ).getTime();

// Get events returned by Google Calendar.
// Ignore empty placeholder items produced by Always Output Data.
const events = $input.all();

const busyPeriods = [];

for (const item of events) {
  const event = item.json;

  const startValue = event.start?.dateTime || event.start?.date;
  const endValue = event.end?.dateTime || event.end?.date;

  if (!startValue || !endValue) {
    continue;
  }

  let startMs;
  let endMs;

  // Timed event
  if (event.start?.dateTime) {
    startMs = new Date(startValue).getTime();
    endMs = new Date(endValue).getTime();
  } else {
    // All-day event.
    // Google Calendar's end date is exclusive.
    startMs = new Date(`${startValue}T00:00:00${zoneOffset}`).getTime();
    endMs = new Date(`${endValue}T00:00:00${zoneOffset}`).getTime();
  }

  if (Number.isNaN(startMs) || Number.isNaN(endMs)) {
    continue;
  }

  // Only keep events that overlap the requested day.
  if (endMs <= dayStartMs || startMs >= nextDayStartMs) {
    continue;
  }

  busyPeriods.push({
    startMs: Math.max(startMs, dayStartMs),
    endMs: Math.min(endMs, nextDayStartMs),
  });
}

const nowMs = Date.now();
const slots = [];

for (
  let slotStartMs = businessStartMs;
  slotStartMs < businessEndMs;
  slotStartMs += slotMinutes * 60 * 1000
) {
  const slotEndMs = slotStartMs + slotMinutes * 60 * 1000;

  if (slotEndMs > businessEndMs) {
    break;
  }

  // Don't offer times that have already passed.
  if (slotStartMs <= nowMs) {
    continue;
  }

  const conflicts = busyPeriods.some(
    ({ startMs, endMs }) =>
      slotStartMs < endMs && slotEndMs > startMs
  );

  if (conflicts) {
    continue;
  }

  const start = new Date(slotStartMs);
  const end = new Date(slotEndMs);

  const formatTime = (d) =>
    new Intl.DateTimeFormat('en-US', {
      timeZone: 'Asia/Riyadh',
      hour: 'numeric',
      minute: '2-digit',
      hour12: true,
    }).format(d);

  slots.push({
    start_time: start.toISOString(),
    end_time: end.toISOString(),
    display: `${formatTime(start)} - ${formatTime(end)}`,
  });
}

return [
  {
    json: {
      success: true,
      date,
      timezone: 'Asia/Riyadh',
      duration_minutes: slotMinutes,
      available_count: slots.length,
      slots,
      message: slots.length
        ? `${slots.length} demo slots are available.`
        : 'No demo slots are available on this date.'
    }
  }
];

const rawDate = $input.first()?.json?.date;
const date = typeof rawDate === 'string' ? rawDate.trim() : '';

const hasCorrectFormat = /^\d{4}-\d{2}-\d{2}$/.test(date);
let isValid = false;

if (hasCorrectFormat) {
  const [year, month, day] = date.split('-').map(Number);
  const parsed = new Date(`${date}T00:00:00.000Z`);

  isValid =
    year >= 1000 &&
    Number.isFinite(parsed.getTime()) &&
    parsed.toISOString().slice(0, 10) === date &&
    month >= 1 &&
    month <= 12 &&
    day >= 1 &&
    day <= 31;
}

return [{
  json: {
    date,
    date_valid: isValid,
    invalid_date: !isValid,
    message: isValid
      ? ''
      : 'The requested date is invalid. Please provide a valid date in YYYY-MM-DD format.'
  }
}];

const item = $input.first()?.json ?? {};
const date = item.date;

if (typeof date !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(date)) {
  throw new Error('A valid date is required.');
}

// Sunday = 0, Monday = 1, ..., Saturday = 6
const weekday = new Date(`${date}T12:00:00.000Z`).getUTCDay();
const isWorkingDay = weekday >= 0 && weekday <= 4;

return [{
  json: {
    ...item,
    weekday,
    is_working_day: isWorkingDay,
  }
}];

const date = $input.first()?.json?.date;

return [{
  json: {
    success: true,
    date,
    timezone: 'Asia/Riyadh',
    duration_minutes: 30,
    available_count: 0,
    slots: [],
    message: 'No demo appointments are offered on this day.',
  }
}];
